def get_embeddings_array() -> "np.ndarray":
    """返回 (N, 384) 的 numpy 数组"""
    if not EMBEDDINGS:
        return np.empty((0, 384), dtype=np.float32)
    return np.array(EMBEDDINGS, dtype=np.float32)
